  "bn": {
    "Lo siento muchísimo. Estoy aquí contigo y te mando un abrazo muy fuerte 💗 Si lo necesitas, habla también con alguien de confianza.": "আমি খুব দুঃখিত। আমি তোমার পাশে আছি, তোমাকে শক্ত করে জড়িয়ে ধরছি 💗 দরকার হলে বিশ্বস্ত কারও সঙ্গেও কথা বলো।",
    "Las legumbres, las espinacas o la carne te ayudan a recuperar el hierro que pierdes.": "ডাল, পালং শাক বা মাংস তোমার হারানো আয়রন ফিরে পেতে সাহায্য করে।",
    "Lo que me has contado": "তুমি আমাকে যা বলেছ",
    "Ver todo en Mi diario ›": "আমার ডায়েরিতে সব দেখো ›",
    "Cuéntaselo a Michi y te contesta 💌": "মিচিকে বলো, সে উত্তর দেবে 💌",
    "Ver más consejos ›": "আরও পরামর্শ ›",
    "Registra tu regla para calcular tu ovulación.": "ওভুলেশন হিসাব করতে তোমার পিরিয়ড লেখো।",
    "Próxima ovulación": "পরবর্তী ওভুলেশন",
    "Hoy estás en tu ventana fértil 🌱": "আজ তুমি তোমার উর্বর সময়ে আছ 🌱",
    "Ventana fértil estimada": "সম্ভাব্য উর্বর সময়",
    "Tus días más fértiles son los 5 días antes de la ovulación y el día siguiente. Son estimaciones según tus registros, no un método anticonceptivo.": "তোমার সবচেয়ে উর্বর দিন হলো ওভুলেশনের আগের ৫ দিন ও তার পরের দিন। এগুলো তোমার রেকর্ড অনুযায়ী অনুমান, জন্মনিয়ন্ত্রণ পদ্ধতি নয়।",
    "Nota del día": "আজকের নোট",
    "Escribe una nota en cualquier día del calendario": "ক্যালেন্ডারের যেকোনো দিনে নোট লেখো",
    "Todas tus notas juntas": "তোমার সব নোট একসাথে",
    "Te avisamos para cambiarte la compresa, el tampón o la copa": "প্যাড, ট্যাম্পন বা কাপ বদলানোর কথা মনে করিয়ে দেব",
    "Análisis, tendencias e informe para el médico": "বিশ্লেষণ, প্রবণতা ও ডাক্তারের জন্য রিপোর্ট",
    "Relaciones con o sin protección": "সুরক্ষাসহ বা ছাড়া সম্পর্ক",
    "Apunta tu peso": "তোমার ওজন লেখো",
    "Cuántas horas duermes": "তুমি কত ঘণ্টা ঘুমাও",
    "Vasos de agua al día": "দিনে কত গ্লাস পানি",
    "Cómo revisarte paso a paso": "ধাপে ধাপে নিজেকে কীভাবে পরীক্ষা করবে",
    "Resumen del mes": "মাসের সারাংশ",
    "Cómo ha ido tu mes": "তোমার মাস কেমন গেল",
    "Dar de comer a Michi": "মিচিকে খাওয়াও",
    "Registra tu día y Michi come": "তোমার দিন লেখো আর মিচি খাবে",
    "Michi te anima": "মিচি তোমার মন ভালো করে",
    "Para los días en que estás de bajón": "মন খারাপের দিনগুলোর জন্য",
    "Si llevas muchos días así, habla con alguien de confianza o con tu médico.": "অনেক দিন ধরে এমন লাগলে কাছের কারও সঙ্গে বা ডাক্তারের সঙ্গে কথা বলো।",
    "No estás sola 💗": "তুমি একা নও 💗",
    "Si piensas en hacerte daño, habla ahora con alguien. Llama al número de emergencias de tu país (112 en Europa). En España también puedes llamar al 024, gratis y a cualquier hora.": "যদি নিজের ক্ষতি করার কথা ভাবো, এখনই কারও সঙ্গে কথা বলো। তোমার দেশের জরুরি নম্বরে ফোন করো (ইউরোপে 112)। স্পেনে 024-এও ফোন করতে পারো, বিনামূল্যে ও যেকোনো সময়।",
    "Lo que sientes es importante. Hoy no tienes que poder con todo 💗": "তোমার অনুভূতি গুরুত্বপূর্ণ। আজ সবকিছু সামলাতে হবে না 💗",
    "Respira hondo conmigo. Paso a paso, que tú puedes 🐾": "আমার সঙ্গে গভীর শ্বাস নাও। ধাপে ধাপে, তুমি পারবে 🐾",
    "Los días malos también pasan. Aquí estoy contigo 🌸": "খারাপ দিনও কেটে যায়। আমি তোমার পাশে আছি 🌸",
    "Date un abrazo de mi parte y haz algo bonito por ti 🤗": "আমার হয়ে নিজেকে একটা আলিঙ্গন দাও আর নিজের জন্য সুন্দর কিছু করো 🤗",
    "Te quedan {} días por recuperar. ¡Yo te ayudo! 🐾": "তোমার আর {} দিন কাজা বাকি। আমি সাহায্য করব! 🐾",
    "Una tarjeta en Hoy desde unos días antes del Ramadán hasta una semana después.": "রমজানের কয়েক দিন আগে থেকে এক সপ্তাহ পর পর্যন্ত \"আজ\"-এ একটি কার্ড।",
    "Que aparezca": "কখন দেখাবে",
    "3 días antes": "৩ দিন আগে",
    "1 semana antes": "১ সপ্তাহ আগে",
    "1 mes antes": "১ মাস আগে",
    "Seré tu ayudante personal en el Ramadán 🌙": "আমি রমজানে তোমার ব্যক্তিগত সহকারী হব 🌙",
    "Te avisaré unos días antes, contaré tus días de regla y te recordaré los días que te queden por recuperar.": "কয়েক দিন আগে জানাব, তোমার পিরিয়ডের দিন গুনব আর বাকি কাজার দিন মনে করিয়ে দেব।",
    "¡Gracias, Michi!": "ধন্যবাদ, মিচি!",
