    "Las legumbres, las espinacas o la carne te ayudan a recuperar el hierro que pierdes.": "Τα όσπρια, το σπανάκι ή το κρέας σε βοηθούν να αναπληρώσεις τον σίδηρο που χάνεις.",
    "Lo que me has contado": "Όσα μου είπες",
