    "Si llevas muchos días así, habla con alguien de confianza o con tu médico.": "Αν νιώθεις έτσι πολλές μέρες, μίλησε με κάποιον που εμπιστεύεσαι ή με τον γιατρό σου.",
    "No estás sola 💗": "Δεν είσαι μόνη 💗",
    "Si piensas en hacerte daño, habla ahora con alguien. Llama al número de emergencias de tu país (112 en Europa). En España también puedes llamar al 024, gratis y a cualquier hora.": "Αν σκέφτεσαι να βλάψεις τον εαυτό σου, μίλησε τώρα με κάποιον. Κάλεσε τον αριθμό έκτακτης ανάγκης της χώρας σου (112 στην Ευρώπη). Στην Ισπανία μπορείς να καλέσεις και το 024, δωρεάν και οποιαδήποτε ώρα.",
