    "Los días malos también pasan. Aquí estoy contigo 🌸": "ખરાબ દિવસો પણ પસાર થઈ જાય છે. હું તમારી સાથે છું 🌸",
    "Date un abrazo de mi parte y haz algo bonito por ti 🤗": "મારા વતી તમારી જાતને ભેટો અને તમારા માટે કંઈક સરસ કરો 🤗",
    "Te quedan {} días por recuperar. ¡Yo te ayudo! 🐾": "હજી {} દિવસ ભરપાઈ કરવાના છે. હું મદદ કરીશ! 🐾",
