    "Para los días en que estás de bajón": "Көңіл-күй түскен күндерге",
    "Si llevas muchos días así, habla con alguien de confianza o con tu médico.": "Көп күннен бері осылай болса, сенімді адаммен немесе дәрігермен сөйлесіңіз.",
    "No estás sola 💗": "Сіз жалғыз емессіз 💗",
    "Si piensas en hacerte daño, habla ahora con alguien. Llama al número de emergencias de tu país (112 en Europa). En España también puedes llamar al 024, gratis y a cualquier hora.": "Өзіңізге зиян келтіруді ойласаңыз, қазір біреумен сөйлесіңіз. Еліңіздің жедел жәрдем нөміріне қоңырау шалыңыз (Еуропада 112). Испанияда 024 нөміріне де тегін әрі кез келген уақытта қоңырау шалуға болады.",
    "Lo que sientes es importante. Hoy no tienes que poder con todo 💗": "Сезімдеріңіз маңызды. Бүгін бәрін көтеруіңіз міндетті емес 💗",
