    "Te quedan {} días por recuperar. ¡Yo te ayudo! 🐾": "Тағы {} күн қаза қалды. Мен көмектесемін! 🐾",
    "Una tarjeta en Hoy desde unos días antes del Ramadán hasta una semana después.": "Рамазаннан бірнеше күн бұрыннан бір аптадан кейінге дейін «Бүгін» бөлімінде карта.",
    "Que aparezca": "Қашан көрсету",
