    "Si llevas muchos días así, habla con alguien de confianza o con tu médico.": "Soki ozali boye mikolo mingi, solola na moto oyo ozali kotyela motema to monganga na yo.",
    "No estás sola 💗": "Ozali yo moko te 💗",
    "Si piensas en hacerte daño, habla ahora con alguien. Llama al número de emergencias de tu país (112 en Europa). En España también puedes llamar al 024, gratis y a cualquier hora.": "Soki ozali kokanisa kosala yo moko mabe, solola na moto sikoyo. Benga nimero ya likama ya mboka na yo (112 na Mpoto). Na Espagne okoki mpe kobenga 024, ofele mpe ntango nyonso.",
    "Lo que sientes es importante. Hoy no tienes que poder con todo 💗": "Oyo ozali koyoka ezali na ntina. Lelo osengeli te komema nyonso 💗",
    "Respira hondo conmigo. Paso a paso, que tú puedes 🐾": "Pema makasi elongo na ngai. Malembe malembe, okoki 🐾",
    "Los días malos también pasan. Aquí estoy contigo 🌸": "Mikolo ya mabe mpe eleki. Nazali elongo na yo 🌸",
    "Date un abrazo de mi parte y haz algo bonito por ti 🤗": "Yamba yo moko na esika na ngai mpe sala eloko ya kitoko mpo na yo 🤗",
    "Te quedan {} días por recuperar. ¡Yo te ayudo! 🐾": "Otikali na mikolo {} ya kozongisa. Nakosalisa yo! 🐾",
    "Una tarjeta en Hoy desde unos días antes del Ramadán hasta una semana después.": "Karte moko na \"Lelo\" banda mikolo mwa liboso ya Ramadan kino poso moko sima.",
