  "ml": {
    "Lo siento muchísimo. Estoy aquí contigo y te mando un abrazo muy fuerte 💗 Si lo necesitas, habla también con alguien de confianza.": "എനിക്ക് വല്ലാത്ത വിഷമമുണ്ട്. ഞാൻ നിന്റെ കൂടെയുണ്ട്, നിന്നെ മുറുകെ കെട്ടിപ്പിടിക്കുന്നു 💗 വേണമെങ്കിൽ വിശ്വസിക്കുന്ന ആരോടെങ്കിലും സംസാരിക്കൂ.",
    "Las legumbres, las espinacas o la carne te ayudan a recuperar el hierro que pierdes.": "പയർവർഗങ്ങൾ, ചീര അല്ലെങ്കിൽ ഇറച്ചി നഷ്ടപ്പെടുന്ന ഇരുമ്പ് തിരികെ നേടാൻ സഹായിക്കും.",
    "Lo que me has contado": "നീ എന്നോട് പറഞ്ഞത്",
    "Ver todo en Mi diario ›": "എന്റെ ഡയറിയിൽ എല്ലാം കാണൂ ›",
    "Cuéntaselo a Michi y te contesta 💌": "മിച്ചിയോട് പറയൂ, അവൻ മറുപടി തരും 💌",
    "Ver más consejos ›": "കൂടുതൽ നുറുങ്ങുകൾ ›",
    "Registra tu regla para calcular tu ovulación.": "അണ്ഡോത്പാദനം കണക്കാക്കാൻ ആർത്തവം രേഖപ്പെടുത്തൂ.",
    "Próxima ovulación": "അടുത്ത അണ്ഡോത്പാദനം",
    "Hoy estás en tu ventana fértil 🌱": "ഇന്ന് നിങ്ങൾ ഫെർട്ടൈൽ വിൻഡോയിലാണ് 🌱",
    "Nota del día": "ഇന്നത്തെ കുറിപ്പ്",
    "Escribe una nota en cualquier día del calendario": "കലണ്ടറിലെ ഏത് ദിവസത്തിലും കുറിപ്പ് എഴുതൂ",
    "Todas tus notas juntas": "നിങ്ങളുടെ എല്ലാ കുറിപ്പുകളും ഒരിടത്ത്",
    "Te avisamos para cambiarte la compresa, el tampón o la copa": "പാഡ്, ടാംപൺ അല്ലെങ്കിൽ കപ്പ് മാറ്റാൻ ഓർമ്മിപ്പിക്കാം",
    "Análisis, tendencias e informe para el médico": "വിശകലനം, പ്രവണതകൾ, ഡോക്ടർക്കുള്ള റിപ്പോർട്ട്",
    "Relaciones con o sin protección": "സുരക്ഷയോടെയോ അല്ലാതെയോ ബന്ധം",
    "Apunta tu peso": "നിങ്ങളുടെ ഭാരം രേഖപ്പെടുത്തൂ",
    "Cuántas horas duermes": "നിങ്ങൾ എത്ര മണിക്കൂർ ഉറങ്ങുന്നു",
    "Vasos de agua al día": "ദിവസം വെള്ളം ഗ്ലാസുകൾ",
    "Cómo revisarte paso a paso": "ഘട്ടം ഘട്ടമായി സ്വയം പരിശോധിക്കുന്നത് എങ്ങനെ",
    "Resumen del mes": "മാസ സംഗ്രഹം",
    "Cómo ha ido tu mes": "നിങ്ങളുടെ മാസം എങ്ങനെയായിരുന്നു",
    "Dar de comer a Michi": "മിച്ചിക്ക് ഭക്ഷണം കൊടുക്കൂ",
    "Registra tu día y Michi come": "നിങ്ങളുടെ ദിവസം രേഖപ്പെടുത്തിയാൽ മിച്ചി കഴിക്കും",
    "Michi te anima": "മിച്ചി നിങ്ങളെ ഉത്സാഹിപ്പിക്കും",
    "Para los días en que estás de bajón": "മനസ്സ് മടുത്ത ദിവസങ്ങൾക്കായി",
    "Si llevas muchos días así, habla con alguien de confianza o con tu médico.": "കുറേ ദിവസമായി ഇങ്ങനെ തോന്നുന്നുവെങ്കിൽ, വിശ്വസ്തനായ ഒരാളോടോ ഡോക്ടറോടോ സംസാരിക്കൂ.",
    "No estás sola 💗": "നിങ്ങൾ ഒറ്റയ്ക്കല്ല 💗",
    "Si piensas en hacerte daño, habla ahora con alguien. Llama al número de emergencias de tu país (112 en Europa). En España también puedes llamar al 024, gratis y a cualquier hora.": "സ്വയം ഉപദ്രവിക്കാൻ ചിന്തിക്കുന്നുവെങ്കിൽ, ഇപ്പോൾ തന്നെ ആരോടെങ്കിലും സംസാരിക്കൂ. നിങ്ങളുടെ രാജ്യത്തെ അടിയന്തര നമ്പറിൽ വിളിക്കൂ (യൂറോപ്പിൽ 112). സ്പെയിനിൽ 024-ലും സൗജന്യമായി എപ്പോൾ വേണമെങ്കിലും വിളിക്കാം.",
    "Lo que sientes es importante. Hoy no tienes que poder con todo 💗": "നിങ്ങളുടെ വികാരങ്ങൾ പ്രധാനമാണ്. ഇന്ന് എല്ലാം താങ്ങേണ്ടതില്ല 💗",
    "Respira hondo conmigo. Paso a paso, que tú puedes 🐾": "എന്നോടൊപ്പം ആഴത്തിൽ ശ്വസിക്കൂ. പടിപടിയായി, നിങ്ങൾക്ക് കഴിയും 🐾",
    "Los días malos también pasan. Aquí estoy contigo 🌸": "മോശം ദിവസങ്ങളും കടന്നുപോകും. ഞാൻ കൂടെയുണ്ട് 🌸",
    "Date un abrazo de mi parte y haz algo bonito por ti 🤗": "എനിക്കുവേണ്ടി നിങ്ങളെത്തന്നെ കെട്ടിപ്പിടിച്ച് നിങ്ങൾക്കായി എന്തെങ്കിലും നല്ലത് ചെയ്യൂ 🤗",
    "Te quedan {} días por recuperar. ¡Yo te ayudo! 🐾": "ഇനി {} ദിവസം വീട്ടാനുണ്ട്. ഞാൻ സഹായിക്കാം! 🐾",
    "Una tarjeta en Hoy desde unos días antes del Ramadán hasta una semana después.": "റമദാന് കുറച്ച് ദിവസം മുമ്പ് മുതൽ ഒരാഴ്ച കഴിയുന്നതുവരെ \"ഇന്ന്\" എന്നതിൽ ഒരു കാർഡ്.",
    "Que aparezca": "എപ്പോൾ കാണിക്കണം",
    "3 días antes": "3 ദിവസം മുമ്പ്",
    "1 semana antes": "1 ആഴ്ച മുമ്പ്",
    "1 mes antes": "1 മാസം മുമ്പ്",
    "Seré tu ayudante personal en el Ramadán 🌙": "റമദാനിൽ ഞാൻ നിങ്ങളുടെ സ്വന്തം സഹായിയാകും 🌙",
    "Te avisaré unos días antes, contaré tus días de regla y te recordaré los días que te queden por recuperar.": "കുറച്ച് ദിവസം മുമ്പേ അറിയിക്കും, ആർത്തവ ദിവസങ്ങൾ എണ്ണും, വീട്ടേണ്ട ദിവസങ്ങൾ ഓർമ്മിപ്പിക്കും.",
    "¡Gracias, Michi!": "നന്ദി, മിച്ചി!",
    "No te queda ningún día por recuperar ✓": "വീട്ടേണ്ട ദിവസങ്ങളില്ല ✓",
    "Tradiciones": "പാരമ്പര്യങ്ങൾ",
    "Fechas especiales, solo si quieres": "പ്രത്യേക ദിവസങ്ങൾ, നിങ്ങൾ ആഗ്രഹിച്ചാൽ മാത്രം",
