    "Las legumbres, las espinacas o la carne te ayudan a recuperar el hierro que pierdes.": "ပဲအမျိုးမျိုး၊ ဟင်းနုနွယ် သို့မဟုတ် အသားသည် ဆုံးရှုံးသော သံဓာတ်ကို ပြန်ဖြည့်ရန် ကူညီသည်။",
