    "Te avisamos para cambiarte la compresa, el tampón o la copa": "ပက်၊ တမ်ပွန် သို့မဟုတ် ခွက်လဲရန် သတိပေးပါမည်",
    "Análisis, tendencias e informe para el médico": "ခွဲခြမ်းစိတ်ဖြာမှု၊ လမ်းကြောင်းနှင့် ဆရာဝန်အတွက် အစီရင်ခံစာ",
