    "No estás sola 💗": "သင် တစ်ယောက်တည်း မဟုတ်ပါ 💗",
    "Si piensas en hacerte daño, habla ahora con alguien. Llama al número de emergencias de tu país (112 en Europa). En España también puedes llamar al 024, gratis y a cualquier hora.": "ကိုယ့်ကိုယ်ကို ထိခိုက်စေရန် စဉ်းစားနေပါက ယခုပင် တစ်စုံတစ်ယောက်နှင့် စကားပြောပါ။ သင့်နိုင်ငံ၏ အရေးပေါ်နံပါတ်ကို ခေါ်ပါ (ဥရောပတွင် 112)။ စပိန်တွင် 024 ကိုလည်း အခမဲ့ အချိန်မရွေး ခေါ်နိုင်သည်။",
