    "Respira hondo conmigo. Paso a paso, que tú puedes 🐾": "ကျွန်မနှင့်အတူ အသက်ပြင်းပြင်း ရှူပါ။ တစ်လှမ်းချင်း၊ သင်လုပ်နိုင်ပါတယ် 🐾",
    "Los días malos también pasan. Aquí estoy contigo 🌸": "မကောင်းသောနေ့များလည်း ကုန်လွန်သွားမည်။ ကျွန်မ သင့်အနားမှာ ရှိတယ် 🌸",
    "Date un abrazo de mi parte y haz algo bonito por ti 🤗": "ကျွန်မကိုယ်စား ကိုယ့်ကိုယ်ကို ဖက်ပြီး ကိုယ့်အတွက် ကောင်းတာတစ်ခု လုပ်ပါ 🤗",
    "Te quedan {} días por recuperar. ¡Yo te ayudo! 🐾": "ပြန်ဖြည့်ရန် {} ရက် ကျန်သေးသည်။ ကျွန်မ ကူညီမယ်! 🐾",
    "Una tarjeta en Hoy desde unos días antes del Ramadán hasta una semana después.": "ရမဒါန်မတိုင်မီ ရက်အနည်းငယ်မှ ပြီးဆုံးပြီး တစ်ပတ်အထိ \"ယနေ့\" တွင် ကတ်တစ်ခု။",
