    "Seré tu ayudante personal en el Ramadán 🌙": "ရမဒါန်တွင် သင့်ကိုယ်ပိုင်အကူအညီပေးသူ ဖြစ်ပါမယ် 🌙",
    "Te avisaré unos días antes, contaré tus días de regla y te recordaré los días que te queden por recuperar.": "ရက်အနည်းငယ်အလိုတွင် အသိပေးမယ်၊ ရာသီလာရက်များကို ရေတွက်မယ်၊ ပြန်ဖြည့်ရမည့်ရက်များကို သတိပေးမယ်။",
    "¡Gracias, Michi!": "ကျေးဇူးပါ မီချီ!",
    "No te queda ningún día por recuperar ✓": "ပြန်ဖြည့်ရမည့်ရက် မကျန်တော့ပါ ✓",
