  "ne": {
    "Lo siento muchísimo. Estoy aquí contigo y te mando un abrazo muy fuerte 💗 Si lo necesitas, habla también con alguien de confianza.": "मलाई धेरै दुःख लाग्यो। म यहीँ तिम्रो साथमा छु, तिमीलाई कसेर अँगालो हाल्छु 💗 चाहिए भने विश्वासिलो कसैसँग पनि कुरा गर।",
    "Las legumbres, las espinacas o la carne te ayudan a recuperar el hierro que pierdes.": "दाल, पालुङ्गो वा मासुले तपाईंले गुमाउने फलाम फिर्ता पाउन मद्दत गर्छ।",
    "Lo que me has contado": "तपाईंले मलाई भनेका कुरा",
    "Ver todo en Mi diario ›": "मेरो डायरीमा सबै हेर्नुहोस् ›",
    "Cuéntaselo a Michi y te contesta 💌": "मिचीलाई भन्नुहोस्, उसले जवाफ दिन्छ 💌",
    "Ver más consejos ›": "थप सुझाव ›",
    "Registra tu regla para calcular tu ovulación.": "डिम्बक्षरण गणना गर्न आफ्नो महिनावारी लेख्नुहोस्।",
    "Próxima ovulación": "अर्को डिम्बक्षरण",
    "Hoy estás en tu ventana fértil 🌱": "आज तपाईं उर्वर अवधिमा हुनुहुन्छ 🌱",
    "Nota del día": "आजको नोट",
    "Escribe una nota en cualquier día del calendario": "क्यालेन्डरको जुनसुकै दिनमा नोट लेख्नुहोस्",
    "Todas tus notas juntas": "तपाईंका सबै नोट एकै ठाउँमा",
    "Te avisamos para cambiarte la compresa, el tampón o la copa": "प्याड, ट्याम्पोन वा कप फेर्न सम्झाउनेछौं",
    "Análisis, tendencias e informe para el médico": "विश्लेषण, प्रवृत्ति र डाक्टरका लागि रिपोर्ट",
    "Relaciones con o sin protección": "सुरक्षासहित वा बिना सम्बन्ध",
    "Apunta tu peso": "आफ्नो तौल लेख्नुहोस्",
    "Cuántas horas duermes": "तपाईं कति घण्टा सुत्नुहुन्छ",
    "Vasos de agua al día": "दिनमा पानीका गिलास",
    "Cómo revisarte paso a paso": "चरणबद्ध रूपमा आफूलाई कसरी जाँच्ने",
    "Resumen del mes": "महिनाको सारांश",
    "Cómo ha ido tu mes": "तपाईंको महिना कस्तो रह्यो",
    "Dar de comer a Michi": "मिचीलाई खुवाउनुहोस्",
    "Registra tu día y Michi come": "आफ्नो दिन लेख्नुहोस् र मिची खान्छ",
    "Michi te anima": "मिचीले तपाईंलाई हौसला दिन्छ",
    "Para los días en que estás de bajón": "मन उदास भएका दिनहरूका लागि",
    "Si llevas muchos días así, habla con alguien de confianza o con tu médico.": "धेरै दिनदेखि यस्तो लागिरहेको छ भने भरोसाको व्यक्ति वा डाक्टरसँग कुरा गर्नुहोस्।",
    "No estás sola 💗": "तपाईं एक्लै हुनुहुन्न 💗",
    "Si piensas en hacerte daño, habla ahora con alguien. Llama al número de emergencias de tu país (112 en Europa). En España también puedes llamar al 024, gratis y a cualquier hora.": "आफूलाई हानि गर्ने सोच आएमा अहिले नै कसैसँग कुरा गर्नुहोस्। आफ्नो देशको आपतकालीन नम्बरमा फोन गर्नुहोस् (युरोपमा ११२)। स्पेनमा ०२४ मा पनि निःशुल्क र जुनसुकै बेला फोन गर्न सकिन्छ।",
    "Lo que sientes es importante. Hoy no tienes que poder con todo 💗": "तपाईंले जे महसुस गर्नुहुन्छ त्यो महत्त्वपूर्ण छ। आज सबै कुरा बोक्नु पर्दैन 💗",
    "Respira hondo conmigo. Paso a paso, que tú puedes 🐾": "मसँगै गहिरो सास लिनुहोस्। बिस्तारै, तपाईं सक्नुहुन्छ 🐾",
    "Los días malos también pasan. Aquí estoy contigo 🌸": "नराम्रा दिन पनि बित्छन्। म तपाईंसँग छु 🌸",
    "Date un abrazo de mi parte y haz algo bonito por ti 🤗": "मेरो तर्फबाट आफूलाई अँगालो हाल्नुहोस् र आफ्नो लागि केही राम्रो गर्नुहोस् 🤗",
    "Te quedan {} días por recuperar. ¡Yo te ayudo! 🐾": "अझै {} दिन पूरा गर्न बाँकी छ। म मद्दत गर्छु! 🐾",
    "Una tarjeta en Hoy desde unos días antes del Ramadán hasta una semana después.": "रमजानभन्दा केही दिनअघिदेखि एक हप्तापछिसम्म \"आज\" मा एउटा कार्ड।",
    "Que aparezca": "कहिले देखाउने",
    "3 días antes": "३ दिनअघि",
    "1 semana antes": "१ हप्ताअघि",
    "1 mes antes": "१ महिनाअघि",
    "Seré tu ayudante personal en el Ramadán 🌙": "रमजानमा म तपाईंको निजी सहयोगी हुनेछु 🌙",
