    "Dar de comer a Michi": "ਮਿਚੀ ਨੂੰ ਖਾਣਾ ਦਿਓ",
    "Registra tu día y Michi come": "ਆਪਣਾ ਦਿਨ ਦਰਜ ਕਰੋ ਅਤੇ ਮਿਚੀ ਖਾਵੇਗੀ",
    "Michi te anima": "ਮਿਚੀ ਤੁਹਾਡਾ ਹੌਸਲਾ ਵਧਾਉਂਦੀ ਹੈ",
    "Para los días en que estás de bajón": "ਉਦਾਸ ਦਿਨਾਂ ਲਈ",
    "Si llevas muchos días así, habla con alguien de confianza o con tu médico.": "ਜੇ ਕਈ ਦਿਨਾਂ ਤੋਂ ਇੰਝ ਲੱਗ ਰਿਹਾ ਹੈ, ਤਾਂ ਕਿਸੇ ਭਰੋਸੇਯੋਗ ਵਿਅਕਤੀ ਜਾਂ ਡਾਕਟਰ ਨਾਲ ਗੱਲ ਕਰੋ।",
    "No estás sola 💗": "ਤੁਸੀਂ ਇਕੱਲੇ ਨਹੀਂ ਹੋ 💗",
    "Si piensas en hacerte daño, habla ahora con alguien. Llama al número de emergencias de tu país (112 en Europa). En España también puedes llamar al 024, gratis y a cualquier hora.": "ਜੇ ਤੁਸੀਂ ਆਪਣੇ ਆਪ ਨੂੰ ਨੁਕਸਾਨ ਪਹੁੰਚਾਉਣ ਬਾਰੇ ਸੋਚ ਰਹੇ ਹੋ, ਤਾਂ ਹੁਣੇ ਕਿਸੇ ਨਾਲ ਗੱਲ ਕਰੋ। ਆਪਣੇ ਦੇਸ਼ ਦੇ ਐਮਰਜੈਂਸੀ ਨੰਬਰ ’ਤੇ ਕਾਲ ਕਰੋ (ਯੂਰਪ ਵਿੱਚ 112)। ਸਪੇਨ ਵਿੱਚ 024 ’ਤੇ ਵੀ ਮੁਫ਼ਤ ਅਤੇ ਕਦੇ ਵੀ ਕਾਲ ਕਰ ਸਕਦੇ ਹੋ।",
    "Lo que sientes es importante. Hoy no tienes que poder con todo 💗": "ਤੁਸੀਂ ਜੋ ਮਹਿਸੂਸ ਕਰਦੇ ਹੋ ਉਹ ਮਾਇਨੇ ਰੱਖਦਾ ਹੈ। ਅੱਜ ਸਭ ਕੁਝ ਚੁੱਕਣ ਦੀ ਲੋੜ ਨਹੀਂ 💗",
    "Respira hondo conmigo. Paso a paso, que tú puedes 🐾": "ਮੇਰੇ ਨਾਲ ਡੂੰਘਾ ਸਾਹ ਲਓ। ਹੌਲੀ-ਹੌਲੀ, ਤੁਸੀਂ ਕਰ ਸਕਦੇ ਹੋ 🐾",
    "Los días malos también pasan. Aquí estoy contigo 🌸": "ਬੁਰੇ ਦਿਨ ਵੀ ਲੰਘ ਜਾਂਦੇ ਹਨ। ਮੈਂ ਤੁਹਾਡੇ ਨਾਲ ਹਾਂ 🌸",
    "Date un abrazo de mi parte y haz algo bonito por ti 🤗": "ਮੇਰੇ ਵੱਲੋਂ ਆਪਣੇ ਆਪ ਨੂੰ ਜੱਫੀ ਪਾਓ ਅਤੇ ਆਪਣੇ ਲਈ ਕੁਝ ਵਧੀਆ ਕਰੋ 🤗",
    "Te quedan {} días por recuperar. ¡Yo te ayudo! 🐾": "ਅਜੇ {} ਦਿਨ ਪੂਰੇ ਕਰਨੇ ਬਾਕੀ ਹਨ। ਮੈਂ ਮਦਦ ਕਰਾਂਗੀ! 🐾",
    "Una tarjeta en Hoy desde unos días antes del Ramadán hasta una semana después.": "ਰਮਜ਼ਾਨ ਤੋਂ ਕੁਝ ਦਿਨ ਪਹਿਲਾਂ ਤੋਂ ਇੱਕ ਹਫ਼ਤੇ ਬਾਅਦ ਤੱਕ \"ਅੱਜ\" ਵਿੱਚ ਇੱਕ ਕਾਰਡ।",
    "Que aparezca": "ਕਦੋਂ ਵਿਖਾਉਣਾ",
    "3 días antes": "3 ਦਿਨ ਪਹਿਲਾਂ",
    "1 semana antes": "1 ਹਫ਼ਤਾ ਪਹਿਲਾਂ",
    "1 mes antes": "1 ਮਹੀਨਾ ਪਹਿਲਾਂ",
    "Seré tu ayudante personal en el Ramadán 🌙": "ਰਮਜ਼ਾਨ ਵਿੱਚ ਮੈਂ ਤੁਹਾਡੀ ਨਿੱਜੀ ਸਹਾਇਕ ਬਣਾਂਗੀ 🌙",
    "Te avisaré unos días antes, contaré tus días de regla y te recordaré los días que te queden por recuperar.": "ਕੁਝ ਦਿਨ ਪਹਿਲਾਂ ਦੱਸਾਂਗੀ, ਤੁਹਾਡੇ ਮਾਹਵਾਰੀ ਦੇ ਦਿਨ ਗਿਣਾਂਗੀ ਅਤੇ ਪੂਰੇ ਕਰਨ ਵਾਲੇ ਦਿਨ ਯਾਦ ਕਰਵਾਵਾਂਗੀ।",
    "¡Gracias, Michi!": "ਸ਼ੁਕਰੀਆ, ਮਿਚੀ!",
    "No te queda ningún día por recuperar ✓": "ਕੋਈ ਦਿਨ ਪੂਰਾ ਕਰਨਾ ਬਾਕੀ ਨਹੀਂ ✓",
    "Tradiciones": "ਪਰੰਪਰਾਵਾਂ",
    "Fechas especiales, solo si quieres": "ਖ਼ਾਸ ਤਾਰੀਖਾਂ, ਸਿਰਫ਼ ਜੇ ਤੁਸੀਂ ਚਾਹੋ",
    "Elige una opción para ver fechas especiales. Se guarda solo en tu móvil y no la recibimos.": "ਖ਼ਾਸ ਤਾਰੀਖਾਂ ਵੇਖਣ ਲਈ ਇੱਕ ਵਿਕਲਪ ਚੁਣੋ। ਇਹ ਸਿਰਫ਼ ਤੁਹਾਡੇ ਫ਼ੋਨ ਵਿੱਚ ਸੰਭਾਲਿਆ ਜਾਂਦਾ ਹੈ, ਸਾਨੂੰ ਨਹੀਂ ਮਿਲਦਾ।",
    "Ninguna": "ਕੋਈ ਨਹੀਂ",
    "Sin fechas especiales": "ਕੋਈ ਖ਼ਾਸ ਤਾਰੀਖ ਨਹੀਂ",
