    "Ramadán: días de regla y días por recuperar": "ਰਮਜ਼ਾਨ: ਮਾਹਵਾਰੀ ਦੇ ਦਿਨ ਅਤੇ ਪੂਰੇ ਕਰਨ ਵਾਲੇ ਦਿਨ",
    "Cristiana": "ਈਸਾਈ",
    "Te felicitamos el día de tu santo": "ਤੁਹਾਡੇ ਸੰਤ ਦਿਵਸ ਦੀ ਵਧਾਈ ਦੇਵਾਂਗੇ",
    "Tu santo": "ਤੁਹਾਡਾ ਸੰਤ ਦਿਵਸ",
    "No encontramos tu santo. Elige el día.": "ਤੁਹਾਡਾ ਸੰਤ ਦਿਵਸ ਨਹੀਂ ਮਿਲਿਆ। ਦਿਨ ਚੁਣੋ।",
