    "Hoy es tu día. Que lo disfrutes mucho 💗": "ਅੱਜ ਤੁਹਾਡਾ ਦਿਨ ਹੈ। ਖ਼ੂਬ ਆਨੰਦ ਮਾਣੋ 💗",
