    "Para los días en que estás de bajón": "සිත කලකිරුණු දිනවලට",
    "Si llevas muchos días así, habla con alguien de confianza o con tu médico.": "බොහෝ දින මෙසේ දැනේ නම්, විශ්වාසවන්ත කෙනෙකු හෝ වෛද්‍යවරයා සමඟ කතා කරන්න.",
    "No estás sola 💗": "ඔබ තනි නැහැ 💗",
    "Si piensas en hacerte daño, habla ahora con alguien. Llama al número de emergencias de tu país (112 en Europa). En España también puedes llamar al 024, gratis y a cualquier hora.": "ඔබට හානි කර ගැනීමට සිතෙනවා නම්, දැන්ම කෙනෙකු සමඟ කතා කරන්න. ඔබේ රටේ හදිසි අංකයට අමතන්න (යුරෝපයේ 112). ස්පාඤ්ඤයේ 024 ටද නොමිලේ ඕනෑම වේලාවක ඇමතිය හැක.",
    "Lo que sientes es importante. Hoy no tienes que poder con todo 💗": "ඔබට දැනෙන දේ වැදගත්. අද හැමදේම දරාගන්න ඕනෑ නැහැ 💗",
    "Respira hondo conmigo. Paso a paso, que tú puedes 🐾": "මා සමඟ ගැඹුරින් හුස්ම ගන්න. පියවරෙන් පියවර, ඔබට පුළුවන් 🐾",
    "Los días malos también pasan. Aquí estoy contigo 🌸": "නරක දවස්ද ගෙවී යනවා. මම ඔබ සමඟ ඉන්නවා 🌸",
    "Date un abrazo de mi parte y haz algo bonito por ti 🤗": "මා වෙනුවෙන් ඔබව බදාගෙන ඔබ වෙනුවෙන් ලස්සන දෙයක් කරන්න 🤗",
    "Te quedan {} días por recuperar. ¡Yo te ayudo! 🐾": "තවත් දින {} ක් පියවිය යුතුයි. මම උදව් කරන්නම්! 🐾",
    "Una tarjeta en Hoy desde unos días antes del Ramadán hasta una semana después.": "රාමසානයට දින කිහිපයකට පෙර සිට සතියක් පසු වනතුරු \"අද\" තුළ කාඩ්පතක්.",
