    "Seré tu ayudante personal en el Ramadán 🌙": "රාමසානයේදී මම ඔබේ පෞද්ගලික සහායිකාව වන්නම් 🌙",
    "Te avisaré unos días antes, contaré tus días de regla y te recordaré los días que te queden por recuperar.": "දින කිහිපයකට පෙර දන්වන්නම්, ඔබේ ඔසප් දින ගණන් කරන්නම් සහ පියවිය යුතු දින මතක් කරන්නම්.",
