  "ta": {
    "Lo siento muchísimo. Estoy aquí contigo y te mando un abrazo muy fuerte 💗 Si lo necesitas, habla también con alguien de confianza.": "எனக்கு மிகவும் வருத்தமாக இருக்கிறது. நான் உன்னுடன் இருக்கிறேன், உன்னை இறுக்கமாக அணைத்துக்கொள்கிறேன் 💗 தேவைப்பட்டால் நம்பிக்கையான ஒருவரிடமும் பேசு.",
    "Las legumbres, las espinacas o la carne te ayudan a recuperar el hierro que pierdes.": "பருப்பு வகைகள், கீரை அல்லது இறைச்சி நீங்கள் இழக்கும் இரும்புச்சத்தை மீட்க உதவும்.",
    "Lo que me has contado": "நீங்கள் என்னிடம் சொன்னவை",
    "Ver todo en Mi diario ›": "என் டைரியில் அனைத்தையும் பார் ›",
    "Cuéntaselo a Michi y te contesta 💌": "மிச்சியிடம் சொல்லுங்கள், அவன் பதில் சொல்வான் 💌",
    "Ver más consejos ›": "மேலும் குறிப்புகள் ›",
    "Registra tu regla para calcular tu ovulación.": "அண்டவிடுப்பைக் கணக்கிட உங்கள் மாதவிடாயைப் பதிவுசெய்யுங்கள்.",
    "Próxima ovulación": "அடுத்த அண்டவிடுப்பு",
    "Hoy estás en tu ventana fértil 🌱": "இன்று நீங்கள் கருவுறும் காலத்தில் உள்ளீர்கள் 🌱",
    "Nota del día": "இன்றைய குறிப்பு",
    "Escribe una nota en cualquier día del calendario": "நாட்காட்டியின் எந்த நாளிலும் குறிப்பு எழுதுங்கள்",
    "Todas tus notas juntas": "உங்கள் எல்லா குறிப்புகளும் ஒரே இடத்தில்",
    "Te avisamos para cambiarte la compresa, el tampón o la copa": "பேட், டேம்பான் அல்லது கப் மாற்ற நினைவூட்டுவோம்",
    "Análisis, tendencias e informe para el médico": "பகுப்பாய்வு, போக்குகள் மற்றும் மருத்துவருக்கான அறிக்கை",
    "Relaciones con o sin protección": "பாதுகாப்புடன் அல்லது இல்லாமல் உறவு",
    "Apunta tu peso": "உங்கள் எடையைப் பதிவுசெய்யுங்கள்",
    "Cuántas horas duermes": "எத்தனை மணி நேரம் தூங்குகிறீர்கள்",
    "Vasos de agua al día": "தினமும் தண்ணீர் கிளாஸ்கள்",
    "Cómo revisarte paso a paso": "படிப்படியாக உங்களைப் பரிசோதிப்பது எப்படி",
    "Resumen del mes": "மாதச் சுருக்கம்",
    "Cómo ha ido tu mes": "உங்கள் மாதம் எப்படி இருந்தது",
    "Dar de comer a Michi": "மிச்சிக்கு உணவளி",
    "Registra tu día y Michi come": "உங்கள் நாளைப் பதிவுசெய்தால் மிச்சி சாப்பிடும்",
    "Michi te anima": "மிச்சி உற்சாகப்படுத்தும்",
    "Para los días en que estás de bajón": "மனம் சோர்ந்த நாட்களுக்கு",
    "Si llevas muchos días así, habla con alguien de confianza o con tu médico.": "பல நாட்களாக இப்படி உணர்ந்தால், நம்பிக்கையான ஒருவரிடமோ மருத்துவரிடமோ பேசுங்கள்.",
    "No estás sola 💗": "நீங்கள் தனியாக இல்லை 💗",
    "Si piensas en hacerte daño, habla ahora con alguien. Llama al número de emergencias de tu país (112 en Europa). En España también puedes llamar al 024, gratis y a cualquier hora.": "உங்களைக் காயப்படுத்திக்கொள்ள நினைத்தால், இப்போதே யாரிடமாவது பேசுங்கள். உங்கள் நாட்டின் அவசர எண்ணை அழையுங்கள் (ஐரோப்பாவில் 112). ஸ்பெயினில் 024 எண்ணையும் இலவசமாக எந்த நேரத்திலும் அழைக்கலாம்.",
    "Lo que sientes es importante. Hoy no tienes que poder con todo 💗": "நீங்கள் உணர்வது முக்கியம். இன்று எல்லாவற்றையும் சுமக்க வேண்டியதில்லை 💗",
    "Respira hondo conmigo. Paso a paso, que tú puedes 🐾": "என்னுடன் ஆழ்ந்து மூச்சு விடுங்கள். படிப்படியாக, உங்களால் முடியும் 🐾",
    "Los días malos también pasan. Aquí estoy contigo 🌸": "கஷ்டமான நாட்களும் கடந்து போகும். நான் உங்களுடன் இருக்கிறேன் 🌸",
    "Date un abrazo de mi parte y haz algo bonito por ti 🤗": "என் சார்பாக உங்களை அணைத்துக்கொண்டு, உங்களுக்காக ஏதாவது நல்லது செய்யுங்கள் 🤗",
    "Te quedan {} días por recuperar. ¡Yo te ayudo! 🐾": "இன்னும் {} நாட்கள் ஈடுசெய்ய வேண்டும். நான் உதவுகிறேன்! 🐾",
    "Una tarjeta en Hoy desde unos días antes del Ramadán hasta una semana después.": "ரமலானுக்கு சில நாட்கள் முன்பிலிருந்து ஒரு வாரம் பின்பு வரை \"இன்று\" பகுதியில் ஒரு கார்டு.",
    "Que aparezca": "எப்போது காட்டுவது",
    "3 días antes": "3 நாட்கள் முன்",
    "1 semana antes": "1 வாரம் முன்",
    "1 mes antes": "1 மாதம் முன்",
    "Seré tu ayudante personal en el Ramadán 🌙": "ரமலானில் உங்கள் தனிப்பட்ட உதவியாளராக இருப்பேன் 🌙",
    "Te avisaré unos días antes, contaré tus días de regla y te recordaré los días que te queden por recuperar.": "சில நாட்கள் முன்பே சொல்வேன், உங்கள் மாதவிடாய் நாட்களை எண்ணுவேன், ஈடுசெய்ய வேண்டிய நாட்களை நினைவூட்டுவேன்.",
    "¡Gracias, Michi!": "நன்றி, மிச்சி!",
    "No te queda ningún día por recuperar ✓": "ஈடுசெய்ய வேண்டிய நாட்கள் இல்லை ✓",
    "Tradiciones": "மரபுகள்",
    "Fechas especiales, solo si quieres": "சிறப்பு நாட்கள், நீங்கள் விரும்பினால் மட்டும்",
    "Elige una opción para ver fechas especiales. Se guarda solo en tu móvil y no la recibimos.": "சிறப்பு நாட்களைக் காண ஒரு விருப்பத்தைத் தேர்வுசெய்யுங்கள். இது உங்கள் போனில் மட்டுமே சேமிக்கப்படும், எங்களுக்கு வராது.",
    "Ninguna": "எதுவுமில்லை",
    "Sin fechas especiales": "சிறப்பு நாட்கள் இல்லை",
    "Musulmana": "முஸ்லிம்",
    "Ramadán: días de regla y días por recuperar": "ரமலான்: மாதவிடாய் நாட்களும் ஈடுசெய்ய வேண்டிய நாட்களும்",
    "Cristiana": "கிறிஸ்தவர்",
    "Te felicitamos el día de tu santo": "உங்கள் புனிதர் தினத்தில் வாழ்த்துவோம்",
    "Tu santo": "உங்கள் புனிதர் தினம்",
    "No encontramos tu santo. Elige el día.": "உங்கள் புனிதர் தினம் கிடைக்கவில்லை. நாளைத் தேர்வுசெய்யுங்கள்.",
    "Elegir día": "நாளைத் தேர்வுசெய்",
    "¡Feliz santo! 🎉": "புனிதர் தின வாழ்த்துகள்! 🎉",
    "¡Feliz santo, {}! 🎉": "புனிதர் தின வாழ்த்துகள், {}! 🎉",
    "Hoy es tu día. Que lo disfrutes mucho 💗": "இன்று உங்கள் நாள். மகிழ்ச்சியாக இருங்கள் 💗",
    "Compresa": "பேட்",
    "Tampón": "டேம்பான்",
    "Copa": "மாதவிடாய் கோப்பை",
    "Braga menstrual": "மாதவிடாய் உள்ளாடை",
    "Hora de cambiarte 🩸": "மாற்றும் நேரம் 🩸",
    "Han pasado {} h. Hora de cambiar: {}.": "{} மணி நேரம் ஆகிவிட்டது. மாற்றும் நேரம்: {}.",
    "Estás con la regla · día {}": "மாதவிடாயில் உள்ளீர்கள் · நாள் {}",
    "Temporizador": "டைமர்",
    "Calor en la tripa": "வயிற்றுக்கு வெப்பம்",
    "Estiramientos suaves": "மெல்லிய நீட்சி",
    "Come algo con hierro": "இரும்புச்சத்து உள்ள உணவு",
    "¿Te avisamos para cambiarte?": "மாற்ற நினைவூட்டவா?",
    "Avisarme en": "நினைவூட்டு",
    "Un tampón no debe llevarse más de 8 horas.": "டேம்பானை 8 மணி நேரத்திற்கு மேல் அணியக்கூடாது.",
    "Empezar ahora": "இப்போது தொடங்கு",
    "Te aviso en {}": "{} கழித்து நினைவூட்டுவேன்",
    "Me he cambiado": "மாற்றிவிட்டேன்",
    "Parar": "நிறுத்து",
    "Próximo periodo previsto": "அடுத்த எதிர்பார்க்கப்படும் மாதவிடாய்",
    "Elige un color": "ஒரு நிறத்தைத் தேர்வுசெய்யுங்கள்",
  },
  "te": {
    "Lo siento muchísimo. Estoy aquí contigo y te mando un abrazo muy fuerte 💗 Si lo necesitas, habla también con alguien de confianza.": "నాకు చాలా బాధగా ఉంది. నేను నీతో ఇక్కడే ఉన్నాను, నిన్ను గట్టిగా హత్తుకుంటున్నాను 💗 అవసరమైతే నమ్మకమైన ఎవరితోనైనా మాట్లాడు.",
    "Las legumbres, las espinacas o la carne te ayudan a recuperar el hierro que pierdes.": "పప్పుధాన్యాలు, పాలకూర లేదా మాంసం మీరు కోల్పోయే ఇనుమును తిరిగి పొందడానికి సహాయపడతాయి.",
    "Lo que me has contado": "మీరు నాకు చెప్పినవి",
    "Ver todo en Mi diario ›": "నా డైరీలో అన్నీ చూడండి ›",
    "Cuéntaselo a Michi y te contesta 💌": "మిచికి చెప్పండి, అతను జవాబిస్తాడు 💌",
    "Ver más consejos ›": "మరిన్ని చిట్కాలు ›",
    "Registra tu regla para calcular tu ovulación.": "అండోత్సర్గాన్ని లెక్కించడానికి మీ పీరియడ్ నమోదు చేయండి.",
    "Próxima ovulación": "తదుపరి అండోత్సర్గం",
    "Hoy estás en tu ventana fértil 🌱": "ఈ రోజు మీరు ఫలవంతమైన కాలంలో ఉన్నారు 🌱",
    "Nota del día": "ఈ రోజు నోట్",
    "Escribe una nota en cualquier día del calendario": "క్యాలెండర్‌లో ఏ రోజైనా నోట్ రాయండి",
    "Todas tus notas juntas": "మీ అన్ని నోట్స్ ఒకే చోట",
    "Te avisamos para cambiarte la compresa, el tampón o la copa": "ప్యాడ్, టాంపాన్ లేదా కప్ మార్చమని గుర్తు చేస్తాం",
    "Análisis, tendencias e informe para el médico": "విశ్లేషణ, ధోరణులు మరియు డాక్టర్ కోసం నివేదిక",
    "Relaciones con o sin protección": "రక్షణతో లేదా లేకుండా సంబంధం",
    "Apunta tu peso": "మీ బరువు నమోదు చేయండి",
    "Cuántas horas duermes": "మీరు ఎన్ని గంటలు నిద్రపోతారు",
    "Vasos de agua al día": "రోజుకు నీటి గ్లాసులు",
    "Cómo revisarte paso a paso": "దశలవారీగా స్వయంగా పరీక్షించుకోవడం",
    "Resumen del mes": "నెల సారాంశం",
    "Cómo ha ido tu mes": "మీ నెల ఎలా గడిచింది",
    "Dar de comer a Michi": "మిచికి తిండి పెట్టండి",
    "Registra tu día y Michi come": "మీ రోజు నమోదు చేస్తే మిచి తింటుంది",
    "Michi te anima": "మిచి మీకు ఉత్సాహం ఇస్తుంది",
    "Para los días en que estás de bajón": "మనసు బాగోలేని రోజుల కోసం",
    "Si llevas muchos días así, habla con alguien de confianza o con tu médico.": "చాలా రోజులుగా ఇలా ఉంటే, నమ్మకమైన వ్యక్తితో లేదా డాక్టర్‌తో మాట్లాడండి.",
    "No estás sola 💗": "మీరు ఒంటరి కాదు 💗",
    "Si piensas en hacerte daño, habla ahora con alguien. Llama al número de emergencias de tu país (112 en Europa). En España también puedes llamar al 024, gratis y a cualquier hora.": "మిమ్మల్ని మీరు హాని చేసుకోవాలని అనిపిస్తే, ఇప్పుడే ఎవరితోనైనా మాట్లాడండి. మీ దేశ అత్యవసర నంబర్‌కు కాల్ చేయండి (యూరప్‌లో 112). స్పెయిన్‌లో 024కి కూడా ఉచితంగా, ఎప్పుడైనా కాల్ చేయవచ్చు.",
    "Lo que sientes es importante. Hoy no tienes que poder con todo 💗": "మీ భావాలు ముఖ్యం. ఈ రోజు అన్నీ మోయాల్సిన అవసరం లేదు 💗",
    "Respira hondo conmigo. Paso a paso, que tú puedes 🐾": "నాతో కలిసి లోతుగా శ్వాస తీసుకోండి. అడుగడుగునా, మీరు చేయగలరు 🐾",
    "Los días malos también pasan. Aquí estoy contigo 🌸": "కష్టమైన రోజులూ గడిచిపోతాయి. నేను మీతో ఉన్నాను 🌸",
    "Date un abrazo de mi parte y haz algo bonito por ti 🤗": "నా తరఫున మిమ్మల్ని మీరు హత్తుకోండి, మీ కోసం ఏదైనా మంచి పని చేయండి 🤗",
    "Te quedan {} días por recuperar. ¡Yo te ayudo! 🐾": "ఇంకా {} రోజులు తిరిగి చేయాలి. నేను సాయం చేస్తా! 🐾",
    "Una tarjeta en Hoy desde unos días antes del Ramadán hasta una semana después.": "రంజాన్‌కు కొన్ని రోజుల ముందు నుంచి ఒక వారం తర్వాత వరకు \"ఈ రోజు\"లో ఒక కార్డ్.",
    "Que aparezca": "ఎప్పుడు చూపాలి",
    "3 días antes": "3 రోజుల ముందు",
    "1 semana antes": "1 వారం ముందు",
    "1 mes antes": "1 నెల ముందు",
    "Seré tu ayudante personal en el Ramadán 🌙": "రంజాన్‌లో మీ వ్యక్తిగత సహాయకురాలిగా ఉంటాను 🌙",
    "Te avisaré unos días antes, contaré tus días de regla y te recordaré los días que te queden por recuperar.": "కొన్ని రోజుల ముందే చెబుతాను, మీ పీరియడ్ రోజులు లెక్కిస్తాను, తిరిగి చేయాల్సిన రోజులు గుర్తు చేస్తాను.",
    "¡Gracias, Michi!": "థ్యాంక్స్, మిచి!",
