    "No estás sola 💗": "Bạn không cô đơn 💗",
    "Si piensas en hacerte daño, habla ahora con alguien. Llama al número de emergencias de tu país (112 en Europa). En España también puedes llamar al 024, gratis y a cualquier hora.": "Nếu bạn nghĩ đến việc làm hại bản thân, hãy nói chuyện với ai đó ngay bây giờ. Gọi số khẩn cấp ở nước bạn (112 ở châu Âu). Ở Tây Ban Nha bạn cũng có thể gọi 024, miễn phí và bất cứ lúc nào.",
