  "yo": {
    "Lo siento muchísimo. Estoy aquí contigo y te mando un abrazo muy fuerte 💗 Si lo necesitas, habla también con alguien de confianza.": "Mo kẹ́dùn gidigidi. Mo wà níbí pẹ̀lú rẹ, mo gbá ọ mọ́ra dáadáa 💗 Bí o bá nílò rẹ̀, bá ẹnì kan tí o gbẹ́kẹ̀lé sọ̀rọ̀ pẹ̀lú.",
    "Las legumbres, las espinacas o la carne te ayudan a recuperar el hierro que pierdes.": "Ẹ̀wà, ẹ̀fọ́ tàbí ẹran ń ràn ọ́ lọ́wọ́ láti rí irin tí o pàdánù padà.",
    "Lo que me has contado": "Ohun tí o sọ fún mi",
    "Ver todo en Mi diario ›": "Wo gbogbo rẹ̀ nínú Ìwé-ìrántí mi ›",
    "Cuéntaselo a Michi y te contesta 💌": "Sọ fún Michi, yóò sì dá ọ lóhùn 💌",
    "Ver más consejos ›": "Àwọn ìmọ̀ràn míì ›",
    "Registra tu regla para calcular tu ovulación.": "Kọ nǹkan oṣù rẹ sílẹ̀ láti ṣírò ìgbà ẹyin.",
    "Próxima ovulación": "Ìgbà ẹyin tó ń bọ̀",
    "Hoy estás en tu ventana fértil 🌱": "Òní o wà nínú àkókò ìlóyún rẹ 🌱",
    "Nota del día": "Àkọsílẹ̀ ọjọ́",
    "Escribe una nota en cualquier día del calendario": "Kọ àkọsílẹ̀ sí ọjọ́ èyíkéyìí lórí kàlẹ́ńdà",
    "Todas tus notas juntas": "Gbogbo àkọsílẹ̀ rẹ papọ̀",
    "Te avisamos para cambiarte la compresa, el tampón o la copa": "A ó rán ọ létí láti pààrọ̀ pádì, támpónì tàbí kọ́ọ̀bù",
    "Análisis, tendencias e informe para el médico": "Ìtúpalẹ̀, àṣà àti ìjábọ̀ fún dókítà",
    "Relaciones con o sin protección": "Ìbálòpọ̀ pẹ̀lú ààbò tàbí láìsí",
    "Apunta tu peso": "Kọ ìwúwo rẹ sílẹ̀",
    "Cuántas horas duermes": "Wákàtí mélòó ni o ń sùn",
    "Vasos de agua al día": "Ife omi lójoojúmọ́",
    "Cómo revisarte paso a paso": "Bí o ṣe lè yẹ ara rẹ wò ní ìgbésẹ̀-ìgbésẹ̀",
    "Resumen del mes": "Àkópọ̀ oṣù",
    "Cómo ha ido tu mes": "Báwo ni oṣù rẹ ṣe lọ",
    "Dar de comer a Michi": "Bọ́ Michi",
    "Registra tu día y Michi come": "Kọ ọjọ́ rẹ sílẹ̀ Michi á jẹun",
    "Michi te anima": "Michi ń fún ọ ní ìṣírí",
    "Para los días en que estás de bajón": "Fún àwọn ọjọ́ tí inú rẹ kò dùn",
    "Si llevas muchos días así, habla con alguien de confianza o con tu médico.": "Tí ó bá ti pẹ́ tí o ti ń rí bẹ́ẹ̀, bá ẹni tí o fọkàn tán tàbí dókítà rẹ sọ̀rọ̀.",
    "No estás sola 💗": "O kò dá wà 💗",
    "Si piensas en hacerte daño, habla ahora con alguien. Llama al número de emergencias de tu país (112 en Europa). En España también puedes llamar al 024, gratis y a cualquier hora.": "Tí o bá ń ronú láti ṣe ara rẹ léṣe, bá ẹnìkan sọ̀rọ̀ báyìí. Pe nọ́ńbà pàjáwìrì orílẹ̀-èdè rẹ (112 ní Yúróòpù). Ní Sípéènì, o tún lè pe 024, ọ̀fẹ́ àti nígbàkigbà.",
    "Lo que sientes es importante. Hoy no tienes que poder con todo 💗": "Ohun tí o ń rò ṣe pàtàkì. Kò pọn dandan kí o gbé gbogbo rẹ̀ lónìí 💗",
    "Respira hondo conmigo. Paso a paso, que tú puedes 🐾": "Mí jinlẹ̀ pẹ̀lú mi. Díẹ̀díẹ̀, o lè ṣe é 🐾",
    "Los días malos también pasan. Aquí estoy contigo 🌸": "Àwọn ọjọ́ burúkú náà ń kọjá. Mo wà pẹ̀lú rẹ 🌸",
